mapper.sql:
from aps_item_param p join mst_item i on i.item_id = p.item_id

  p.plant_cd = #{c.plantCd}
  and p.use_yn = #{c.useYn}
  and (i.item_cd ilike #{c.keyword} escape '\' or i.item_nm ilike #{c.keyword} escape '\')

mapper.select:
select 
  from aps_item_param p join mst_item i on i.item_id = p.item_id
 where p.param_id = #{id}

mapper.update:
update aps_item_param
   set safety_qty = #{v.safetyQty}, lot_rule = #{v.lotRule}, lot_qty = #{v.lotQty}, lot_mult = #{v.lotMult},
       make_lead_days = #{v.makeLeadDays}, fence_days = #{v.fenceDays}, remark = #{v.remark}, use_yn = #{v.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where param_id = #{id} and row_ver = #{rowVer}
